          title: "Bilde",
          options: {
            hotspot: true,
          },
          fields: [
            defineField({
              title: "Bildetekst",
              name: "caption",
              type: "string",
            }),
            defineField({
              name: "alt",
              type: "string",
              title: "Alt-tekst",
              description:
                "Alternativ tekst til bildet, for tilgjengelighet for blinde og svaksynte.",
            }),
          ],
        }),
        defineField({
          type: "youtube",
          name: "YouTube",
          description: "Sett inn YouTube-video.",
        }),
        defineField({
          type: "twitter",
          name: "Twitter",
          description: "Sett inn Twitter-tweet.",
